struct O{char op='x';int a=-1,b=-1;long upper=0;string den;};
int main(int argc,char**argv){assert(argc==3);folder=argv[2];began=chrono::steady_clock::now();fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);int status=0;{
 try{ifstream f(argv[1]);int n;f>>reserve_terms>>n;assert(reserve_terms==3564&&n==76);vector<O>ops(n);vector<unique_ptr<L>>v(n);vector<int>uses(n);ofstream audit(folder+"/node-audit.jsonl");int evaluated=0;
  for(int i=0;i<n;i++){auto&o=ops[i];f>>o.op;if(o.op=='x')continue;f>>o.upper>>o.den;if(o.op=='p'){long s;string unit;f>>s>>unit;v[i]=make_unique<L>(readpoly(f));fmpq_t c;fmpq_init(c);assert(!fmpq_set_str(c,unit.c_str(),10));fmpq_canonicalise(c);fmpq_mpoly_scalar_div_fmpq(v[i]->p,v[i]->p,c,ctx);fmpq_clear(c);v[i]->a+=s;normal(*v[i]);}else{f>>o.a>>o.b;uses[o.a]++;uses[o.b]++;}}
  vector<int>outputs(3),col(4),anchor(4),saved;for(int&i:outputs)f>>i;for(int&i:col)f>>i;for(int&i:anchor)f>>i;saved=outputs;saved.insert(saved.end(),col.begin(),col.end());saved.insert(saved.end(),anchor.begin(),anchor.end());for(int i:outputs)uses[i]++;string extra;assert(!(f>>extra));bounded();
  for(int i=0;i<n;i++){auto&o=ops[i];if(o.op=='x')continue;lastnode=i;if(o.op!='p')v[i]=make_unique<L>(operate(*v[o.a],*v[o.b],o.op));assert(fmpq_mpoly_length(v[i]->p,ctx)<=o.upper);fmpz_t D;fmpz_init(D);assert(!fmpz_set_str(D,o.den.c_str(),10));assert(fmpz_divisible(D,fmpq_denref(v[i]->p->content)));fmpz_clear(D);bounded(o.op=='p'?0:fmpq_mpoly_length(v[i]->p,ctx));audit<<"{\"node\":"<<i<<",\"terms\":"<<fmpq_mpoly_length(v[i]->p,ctx)<<",\"a_shift\":"<<v[i]->a<<"}\n";if(find(saved.begin(),saved.end(),i)!=saved.end())savepoly(i,*v[i]);if(o.op!='p'){if(!--uses[o.a])v[o.a].reset();if(!--uses[o.b])v[o.b].reset();}evaluated++;}
  assert(evaluated==62);vector<bool>zeros;vector<long>counts;for(int i:outputs){assert(v[i]);zeros.push_back(zero(*v[i]));counts.push_back(fmpq_mpoly_length(v[i]->p,ctx));}v.clear();
  for(int i=1;i<4;i++){auto out=loadpoly(outputs[i-1]);auto a=loadpoly(anchor[i]),b=loadpoly(col[0]);auto p=make_unique<L>(operate(*a,*b,'m'));a.reset();b.reset();auto next=make_unique<L>(operate(*out,*p,'a'));out.reset();p.reset();auto c=loadpoly(anchor[0]),d=loadpoly(col[i]);auto q=make_unique<L>(operate(*c,*d,'m'));c.reset();d.reset();auto diff=make_unique<L>(operate(*next,*q,'s'));next.reset();q.reset();assert(zero(*diff));diff.reset();bounded();}
  ofstream out(folder+"/native.json");out<<"{\"all_passed\":true,\"all62_source_ops_checked\":true,\"all4_column18_values_and_anchors_and3_outputs_saved\":true,\"independent3_rawcross_readback_reproducts_zero\":true,\"raw_cross3_zero\":[";for(int i=0;i<3;i++){if(i)out<<',';out<<(zeros[i]?"true":"false");}out<<"],\"output_terms\":[";for(int i=0;i<3;i++){if(i)out<<',';out<<counts[i];}out<<"],\"max_total_live_coefficient_slots\":"<<precise_peak<<",\"all_inplace_exponent_RF_identities_preserved\":true,\"NO_kappa18_evaluation\":true,\"no_other_column_determinant_point_prime\":true,\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-began).count()<<"}\n";out.close();files_guard();
 }catch(const exception&e){status=2;ofstream o(folder+"/frontier.json");o<<"{\"all_passed\":false,\"reason\":\""<<e.what()<<"\",\"last_source_node\":"<<lastnode<<",\"max_slots\":"<<precise_peak<<",\"no_auto_retry\":true}\n";}}
 fmpq_mpoly_ctx_clear(ctx);flint_cleanup();return status;}
